async (DP, times, out, sleep, rnd) => {
  const dp = new DP();
  const owner = [null, null, null, null, null];
  const held = [[], [], [], [], []];
  const fork = (p, side) => side === "L" ? p : (p + 4) % 5;
  const take = async (p, side) => { const f = fork(p, side); await sleep(rnd() * 2); if (owner[f] !== null) out.push("CONFLICT вилка " + f); owner[f] = p; held[p].push(f); };
  const put = async (p, side) => { const f = fork(p, side); await sleep(rnd() * 2); if (owner[f] === p) owner[f] = null; held[p] = held[p].filter((x) => x !== f); };
  await Promise.all([0, 1, 2, 3, 4].map(async (p) => {
    for (let k = 0; k < times; k++) {
      await sleep(rnd() * 4);
      await dp.wantsToEat(p,
        () => take(p, "L"), () => take(p, "R"),
        async () => { if (held[p].length !== 2) out.push("EAT_WITHOUT_FORKS " + p); else out.push("eat" + p); await sleep(rnd() * 3); },
        () => put(p, "L"), () => put(p, "R"));
    }
  }));
}

