(out, times) => {
  const bad = out.find((x) => x.startsWith("CONFLICT") || x.startsWith("EAT"));
  if (bad) return bad;
  for (let p = 0; p < 5; p++) if (out.filter((x) => x === "eat" + p).length !== times) return "философ " + p + " поел не " + times + " раз";
  return true;
}

