async (Q, [cap, P, C, N], out, sleep, rnd) => {
  const q = new Q(cap);
  let next = 0;
  const got = [];
  const producers = Array.from({ length: P }, async () => {
    while (next < N) { const x = next++; await sleep(rnd() * 2); await q.enqueue(x); if (q.size() > cap) out.push("OVERFLOW " + q.size()); }
  });
  const per = Math.floor(N / C), extra = N % C;
  const consumers = Array.from({ length: C }, async (_, c) => {
    for (let k = 0; k < per + (c < extra ? 1 : 0); k++) { await sleep(rnd() * 2); got.push(await q.dequeue()); }
  });
  await Promise.all([...producers, ...consumers]);
  out.push(...got.sort((a, b) => a - b));
}

